import{_ as n,o as s,c as t,a6 as e}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"收尾复盘","description":"全专栏的决策速查、常见错误索引，以及一条从零开始的完整路径。","frontmatter":{"title":"收尾复盘","description":"全专栏的决策速查、常见错误索引，以及一条从零开始的完整路径。","source":"https://daiw.org/manual/huggingface/recap"},"headers":[],"relativePath":"manual/llm/huggingface/recap.md","filePath":"manual/llm/huggingface/recap.md"}'),r={name:"manual/llm/huggingface/recap.md"};function l(i,a,p,d,o,h){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="收尾复盘" tabindex="-1">收尾复盘 <a class="header-anchor" href="#收尾复盘" aria-label="Permalink to &quot;收尾复盘&quot;">​</a></h1><blockquote><p>全专栏的决策速查、常见错误索引，以及一条从零开始的完整路径。</p></blockquote><h2 id="三条主线" tabindex="-1">三条主线 <a class="header-anchor" href="#三条主线" aria-label="Permalink to &quot;三条主线&quot;">​</a></h2><p>整个专栏其实只在回答三个问题：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 怎么把模型拿到手     → 格式怎么选、从哪下、国内怎么办</span></span>
<span class="line"><span>② 怎么让它跑起来       → 显存够不够、用哪套推理栈</span></span>
<span class="line"><span>③ 怎么让它变成我的     → 数据怎么整、怎么微调、怎么发布</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="决策速查" tabindex="-1">决策速查 <a class="header-anchor" href="#决策速查" aria-label="Permalink to &quot;决策速查&quot;">​</a></h2><h3 id="下载" tabindex="-1">下载 <a class="header-anchor" href="#下载" aria-label="Permalink to &quot;下载&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>国内？        → HF_ENDPOINT=https://hf-mirror.com，或用 ModelScope</span></span>
<span class="line"><span>只要权重？     → allow_patterns=[&quot;*.safetensors&quot;,&quot;*.json&quot;,&quot;*.jinja&quot;,&quot;*.model&quot;,&quot;*.txt&quot;]</span></span>
<span class="line"><span>GGUF 仓库？    → 必须 --include 指定量化档，否则全下</span></span>
<span class="line"><span>要部署/进容器？ → --local-dir，别用缓存（符号链接跨层易断）</span></span>
<span class="line"><span>生产环境？     → 钉 commit hash，不用分支名</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="选模型" tabindex="-1">选模型 <a class="header-anchor" href="#选模型" aria-label="Permalink to &quot;选模型&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>显存 4G   → 4B int4，或纯 CPU 走 GGUF</span></span>
<span class="line"><span>显存 8G   → 8B Q4_K_M / AWQ        ← 最常见</span></span>
<span class="line"><span>显存 12G  → 8B int8，可开始 QLoRA 微调</span></span>
<span class="line"><span>显存 16G  → 8B bf16，QLoRA 微调舒服</span></span>
<span class="line"><span>显存 24G  → 32B int4，或 14B 微调   ← 甜点</span></span>
<span class="line"><span>纯 CPU    → 16G 内存跑 8B Q4，约 5~10 token/s</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><strong>同显存下优先“大模型 + 重量化”。</strong></p><h3 id="部署" tabindex="-1">部署 <a class="header-anchor" href="#部署" aria-label="Permalink to &quot;部署&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单人本地用       → Ollama</span></span>
<span class="line"><span>没有 N 卡 / Mac  → llama.cpp（-ngl 按显存调）</span></span>
<span class="line"><span>要接进 Python    → transformers（dtype=&quot;auto&quot; 必写）</span></span>
<span class="line"><span>有并发、要吞吐    → vLLM（--max-model-len 别用模型上限）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="训练" tabindex="-1">训练 <a class="header-anchor" href="#训练" aria-label="Permalink to &quot;训练&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>想让模型“知道”内容    → RAG，不是微调</span></span>
<span class="line"><span>想让模型“按某种方式说” → LoRA</span></span>
<span class="line"><span>显存 12~16G           → QLoRA（4bit 基座）</span></span>
<span class="line"><span>起手参数              → r=16, alpha=32, lr=2e-4, target_modules=&quot;all-linear&quot;</span></span>
<span class="line"><span>数据量                → 先 500~1000 条精数据，别一上来堆 10 万</span></span>
<span class="line"><span>epoch                → 数据越少轮数越少，500 条跑 1~2 轮</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="常见错误索引" tabindex="-1">常见错误索引 <a class="header-anchor" href="#常见错误索引" aria-label="Permalink to &quot;常见错误索引&quot;">​</a></h2><p>按出现频率排。<strong>这张表是整个专栏最实用的部分</strong>——遇到问题先在这里找。</p><table tabindex="0"><thead><tr><th>症状</th><th>原因</th><th>在哪一章</th></tr></thead><tbody><tr><td>8B 模型占了 32 G 显存</td><td>没写 <code>dtype=&quot;auto&quot;</code>（或 <code>torch_dtype=&quot;auto&quot;</code>），默认 fp32</td><td><a href="/Front2Full/manual/llm/huggingface/transformers-serving">transformers</a></td></tr><tr><td>模型答非所问 / 输出乱</td><td>没用 <code>apply_chat_template</code></td><td><a href="/Front2Full/manual/llm/huggingface/transformers-serving">transformers</a></td></tr><tr><td>输出里带着自己的提问</td><td>忘了切 <code>inputs.input_ids.shape[1]:</code></td><td><a href="/Front2Full/manual/llm/huggingface/transformers-serving">transformers</a></td></tr><tr><td>模型停不下来一直生成</td><td><code>eos_token_id</code> 不对，漏下 <code>generation_config.json</code></td><td><a href="/Front2Full/manual/llm/huggingface/repo-anatomy">仓库结构</a></td></tr><tr><td>下载 401</td><td>gated 模型没在网页同意条款</td><td><a href="/Front2Full/manual/llm/huggingface/what-is-huggingface">认识 Hub</a></td></tr><tr><td>设了镜像还连官方</td><td><code>os.environ</code> 写在 <code>import</code> 之后</td><td><a href="/Front2Full/manual/llm/huggingface/china-access">国内访问</a></td></tr><tr><td>下了几十 G 用不上的东西</td><td>GGUF 仓库没加 <code>--include</code></td><td><a href="/Front2Full/manual/llm/huggingface/downloading">下载</a></td></tr><tr><td>加载报“找不到文件”</td><td>漏下 <code>model.safetensors.index.json</code></td><td><a href="/Front2Full/manual/llm/huggingface/repo-anatomy">仓库结构</a></td></tr><tr><td>模型“忘了”前面的对话</td><td>Ollama 默认上下文只有 4096</td><td><a href="/Front2Full/manual/llm/huggingface/gguf-llamacpp-ollama">GGUF 路线</a></td></tr><tr><td>vLLM 启动就 OOM</td><td><code>--max-model-len</code> 用了模型上限</td><td><a href="/Front2Full/manual/llm/huggingface/vllm-serving">vLLM</a></td></tr><tr><td>聊长了就 OOM</td><td>KV cache 随上下文增长</td><td><a href="/Front2Full/manual/llm/huggingface/choose-by-vram">选模型</a></td></tr><tr><td><code>map</code> 里报类型错误</td><td><code>batched=True</code> 时收到的是列的字典</td><td><a href="/Front2Full/manual/llm/huggingface/datasets-basics">datasets</a></td></tr><tr><td>训练 loss 掉到 0</td><td>数据重复 / 过拟合 / 泄漏</td><td><a href="/Front2Full/manual/llm/huggingface/training-practice">训练实操</a></td></tr><tr><td>训到一半 OOM</td><td>某几条超长样本</td><td><a href="/Front2Full/manual/llm/huggingface/training-practice">训练实操</a></td></tr><tr><td>微调后通用能力变差</td><td>灾难性遗忘</td><td><a href="/Front2Full/manual/llm/huggingface/training-practice">训练实操</a></td></tr><tr><td>别人下了模型用不了</td><td>忘传 tokenizer</td><td><a href="/Front2Full/manual/llm/huggingface/push-to-hub">推回 Hub</a></td></tr><tr><td>“这月账单怎么这么多”</td><td>忘删的 Endpoint / GPU Space</td><td><a href="/Front2Full/manual/llm/huggingface/paid-tiers">收费版</a></td></tr></tbody></table><h2 id="一条从零开始的完整路径" tabindex="-1">一条从零开始的完整路径 <a class="header-anchor" href="#一条从零开始的完整路径" aria-label="Permalink to &quot;一条从零开始的完整路径&quot;">​</a></h2><p>如果你想把整个流程走一遍，这是最短的可行序列：</p><p><strong>① 环境（10 分钟）</strong></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HF_HOME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/data/hf                        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 别撑满系统盘</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HF_ENDPOINT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://hf-mirror.com       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 国内</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> huggingface_hub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> transformers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> torch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> accelerate</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>② 跑通一个小模型（10 分钟）</strong></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen3:4b</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>先确认“模型能在我机器上跑”这件事，再谈别的。</p><p><strong>③ 接进代码（20 分钟）</strong></p><p>用 <a href="/Front2Full/manual/llm/huggingface/transformers-serving">transformers 那一章</a>的最小例子，跑通 <code>apply_chat_template</code> + <code>generate</code> + 切输出。</p><p><strong>④ 准备 200 条数据（半天）</strong></p><p>按<a href="/Front2Full/manual/llm/huggingface/build-your-dataset">做数据集</a>的对话格式，先做 200 条——<strong>不是 2 万条</strong>。人工过一遍。</p><p><strong>⑤ 跑通训练（1 小时）</strong></p><p>用<a href="/Front2Full/manual/llm/huggingface/finetune-lora">微调那一章</a>的脚本，先 <code>max_steps=10</code> 跑通，再放开。</p><p><strong>⑥ 验收（1 小时）</strong></p><p>准备 20 条训练集外的输入，训练前后对比。再测几条无关问题，确认没训傻。</p><p><strong>⑦ 发布（20 分钟）</strong></p><p><code>push_to_hub(private=True)</code>，写清 <code>base_model</code> 与已知局限，从零加载验证一遍。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>整条路径一天之内能走完，前提是每一步都用小规模。</strong></p><p>最常见的失败模式是“第四步就做了 2 万条数据、第五步直接全量训”——出了问题根本不知道是哪一环的锅。</p><p><strong>小步快跑，每步都验证</strong>，比一次做对更快。</p></div><h2 id="几条不随版本变化的经验" tabindex="-1">几条不随版本变化的经验 <a class="header-anchor" href="#几条不随版本变化的经验" aria-label="Permalink to &quot;几条不随版本变化的经验&quot;">​</a></h2><p><strong>① 先跑通，再跑好。</strong> 小模型、小数据、少步数把全链路打通，再逐项放大。</p><p><strong>② 质量比数量重要。</strong> 1000 条精数据胜过 10 万条粗数据——尤其对 LoRA。</p><p><strong>③ 效果不好先看数据。</strong> 顺序是数据 → 超参 → 模型规模，不是反过来。</p><p><strong>④ 微调不灌知识。</strong> 要模型“知道”什么，用 RAG；微调是教它“怎么说”。</p><p><strong>⑤ 量化的性价比被低估。</strong> 4bit 让硬件门槛直接降一档，质量损失通常可接受。</p><p><strong>⑥ 很多任务不需要 LLM。</strong> 分类、NER、语义匹配，几百 MB 的小模型又快又稳。</p><p><strong>⑦ 定期清理花钱的资源。</strong> 这一条省下的钱，往往比所有技术优化加起来还多。</p><h2 id="继续往下走" tabindex="-1">继续往下走 <a class="header-anchor" href="#继续往下走" aria-label="Permalink to &quot;继续往下走&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想深入</th><th>去哪</th></tr></thead><tbody><tr><td>Transformer 到底怎么工作的</td><td><a href="https://daiw.org/manual/llm-anatomy" target="_blank" rel="noreferrer">《AI 大模型解构》</a></td></tr><tr><td>2026 前沿旗舰架构拆解</td><td><a href="https://daiw.org/manual/deepseek-v4-flash" target="_blank" rel="noreferrer">《DeepSeek V4.1 Flash 深度解析》</a>、<a href="https://daiw.org/manual/qwen3-8-max" target="_blank" rel="noreferrer">《Qwen3.8-Max 深度解析》</a>、<a href="https://daiw.org/manual/kimi-k3" target="_blank" rel="noreferrer">《Kimi K3 深度解析》</a></td></tr><tr><td>从零实现一个 GPT</td><td><a href="https://daiw.org/manual/nanogpt" target="_blank" rel="noreferrer">《nanoGPT 源码解读》</a></td></tr><tr><td>PyTorch 底层机制</td><td><a href="https://daiw.org/manual/pytorch-internals" target="_blank" rel="noreferrer">《PyTorch 源码漫游》</a></td></tr><tr><td>从比特到 AGI 的完整路径</td><td><a href="https://daiw.org/manual/bit-to-agi" target="_blank" rel="noreferrer">《从 Bit 到 AGI》</a></td></tr><tr><td>把模型接成 Agent</td><td><a href="https://daiw.org/manual/llm-to-agent" target="_blank" rel="noreferrer">《从 LLM 到 Coding Agent》</a></td></tr></tbody></table><p>官方资源：</p><ul><li><a href="https://huggingface.co/docs" target="_blank" rel="noreferrer">HuggingFace Docs</a> —— 权威且更新快</li><li><a href="https://huggingface.co/learn" target="_blank" rel="noreferrer">HF 社区课程</a> —— 免费，有 NLP / 深度强化学习 / Agent 等方向</li><li><a href="https://huggingface.co" target="_blank" rel="noreferrer">Hub 模型页的 Community 标签</a> —— 别人踩过的坑常在这里</li></ul><hr><p>回到<a href="/Front2Full/manual/llm/huggingface/">专栏首页</a>可查任意章节。</p><p><strong>这个专栏讲的所有东西，本质上只是让你能自由地取用别人的成果、再把自己的东西还回去。</strong> Hub 上那上百万个模型，每一个都是有人训完传上来的——你也可以是其中之一。</p>`,51)])])}const g=n(r,[["render",l]]);export{u as __pageData,g as default};
